codeExamples.code:
-- Newest orders first; ties broken by amount ascending
SELECT order_id, customer_id, order_date, amount
FROM orders
ORDER BY order_date DESC, amount ASC;

-- ASC is the default, so these are equivalent
SELECT * FROM orders ORDER BY amount;
SELECT * FROM orders ORDER BY amount ASC;

-- DESC applies only to the key it follows;
-- here last_name is DESC but first_name is ASC (default)
SELECT last_name, first_name
FROM employees
ORDER BY last_name DESC, first_name;
